INSERT INTO `modulo` (`id_modulo`, `descricao`, `conteudo`, `id_curso`, `created_at`, `updated_at`) VALUES
(6, 'OFICINA DE ELABORAÇÃO DO PMAS E PMEP', '<b>PROGRAMAÇÃO\r\nDAS OFICINAS DO PLANO MUNICIPAL DE ASSISTÊNCIA SOCIAL E PLANO MUNICIPAL DE EDUCAÇÃO PERMANENTE DO SUAS</b>\r\n\r\n\r\n\r\n<p><b>1º Dia  - PLANO MUNICIPAL DE ASSISTÊNCIA SOCIAL</b></p>\r\n\r\n<p>8h - apresentação e dinâmica.</p>\r\n\r\n<p>8h30 -<b> </b>Trabalho<b> </b>em grupo\r\nreferente às atribuições da SEMAS.</p>\r\n\r\n<p>9h - apresentação dos trabalhos em\r\ngrupo.</p>\r\n\r\n<p>9h30- intervalo.</p>\r\n\r\n<p>9h45- apresentação sobre o SUAS,\r\nplanejamento e estrutura do plano municipal de assistência social - PMAS.</p>\r\n\r\n<p>12h – Almoço.</p>\r\n\r\n<p>14h – Dinâmica.</p>\r\n\r\n<p>14H30 - Atividade em grupo: estrutura\r\ndo PMAS de acordo com o artigo 18 da NOB-SUAS.</p>\r\n\r\n<p>15h30 - Intervalo</p>\r\n\r\n<p>15h45 – apresentação dos grupos sobre cada\r\ntópico do PMAS.<br></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><b>2º Dia &nbsp;</b><b>PLANO\r\nMUNICIPAL DE </b><b>EDUCAÇÃO PERMANENTE</b> <br></p>\r\n\r\n<p>8h - Dinâmica.</p>\r\n\r\n<p>8h30h – Música: Cidadão (Zé Ramalho); Comida (Titãs) e debate sobre as condições de trabalhos, o que é trabalho e quem\r\né o trabalhador do SUAS. </p>\r\n\r\n<p>9h - Vídeo sobre a Política Nacional\r\nde Educação Permanente – PNEP.</p>\r\n\r\n<p>9h40\r\n– Intervalo.</p>\r\n\r\n<p>9h55–\r\nApresentação sobre gestão do trabalho, educação permanente e estrutura do Plano\r\nde Educaçao Permanente – PMEP. </p>\r\n\r\n<p>12h\r\n– almoço.</p>\r\n\r\n<p>14h\r\n– Dinâmica</p>\r\n\r\n<p>14h30\r\n– Atividade em grupo – Tema: valorização e qualificação do trabalhador.</p>\r\n\r\n<p>15h30\r\n– Intervalo.</p>\r\n\r\n<p>15h45\r\n– Apresentação dos trabalhos.  &nbsp; </p>\r\n\r\n<p><b>&nbsp;</b></p>\r\n\r\n<p><b>3º Dia &nbsp;</b><b>ORÇAMENTO E\r\nFINANÇAS NA POLÍTICA DE ASSISTÊNCIA SOCIAL </b><b></b></p>\r\n\r\n<p>8h - Dinâmica.</p>\r\n\r\n<p>8h30h – Estrutura do PPA, orçamento e\r\nfinanças na assistência Social</p>\r\n\r\n<p>9h30 – Trabalho em grupo</p>\r\n\r\n<p>10h30 – Intervalo</p>\r\n\r\n<p>10h45 – Retorno do trabalho em grupo e\r\napresentação de vídeos</p>\r\n\r\n<p>12h – Almoço</p>\r\n\r\n<p>14h – Dinâmica </p>\r\n\r\n<p>14h30 - Avaliação da oficina.</p>', 78, '2017-08-08 16:42:17', '2017-08-08 17:11:14'),
(7, 'OFICINA DE ELABORAÇÃO DO PMAS E PMEP', '<p><b>PROGRAMAÇÃO\r\nDAS OFICINAS DO PLANO MUNICIPAL DE ASSISTÊNCIA SOCIAL E PLANO MUNICIPAL DE\r\nEDUCAÇÃO PERMANENTE DO SUAS</b>\r\n\r\n\r\n\r\n\r\n\r\n&nbsp;<b><br></b></p><p><b>1º Dia  - PLANO MUNICIPAL DE ASSISTÊNCIA SOCIAL</b>\r\n\r\n\r\n\r\n</p><p>8h - apresentação e dinâmica.</p>\r\n\r\n<p>8h30 -<b> </b>Trabalho<b> </b>em grupo\r\nreferente às atribuições da SEMAS.</p>\r\n\r\n<p>9h - apresentação dos trabalhos em\r\ngrupo.</p>\r\n\r\n<p>9h30- intervalo.</p>\r\n\r\n<p>9h45- apresentação sobre o SUAS,\r\nplanejamento e estrutura do plano municipal de assistência social - PMAS.</p>\r\n\r\n<p>12h – Almoço.</p>\r\n\r\n<p>14h – Dinâmica.</p>\r\n\r\n<p>14H30 - Atividade em grupo: estrutura\r\ndo PMAS de acordo com o artigo 18 da NOB-SUAS.</p>\r\n\r\n<p>15h30 - Intervalo</p>\r\n\r\n<p>15h45 – apresentação dos grupos sobre cada\r\ntópico do PMAS.<b></b></p>\r\n\r\n<p><b>2º Dia &nbsp;</b><b>PLANO\r\nMUNICIPAL DE </b><b>EDUCAÇÃO PERMANENTE</b><b></b></p>\r\n\r\n<p>&nbsp;8h - Dinâmica.\r\n\r\n</p><p>8h30h – Música: Cidadão (Zé Ramalho) e\r\nComida (Titãs) e debate sobre as condições de trabalhos, o que é trabalho...quem\r\né o trabalhador do SUAS.... </p>\r\n\r\n<p>9h - Vídeo sobre a Política Nacional\r\nde Educação Permanente – PNEP.</p>\r\n\r\n<p>9h40\r\n– Intervalo.</p>\r\n\r\n<p>9h55–\r\nApresentação sobre gestão do trabalho, educação permanente e estrutura do Plano\r\nde Educaçao Permanente – PMEP. </p>\r\n\r\n<p>12h\r\n– almoço.</p>\r\n\r\n<p>14h\r\n– Dinâmica</p>\r\n\r\n<p>14h30\r\n– Atividade em grupo – Tema: valorização e qualificação do trabalhador.</p>\r\n\r\n<p>15h30\r\n– Intervalo.</p>\r\n\r\n<p>15h45\r\n– Apresentação dos trabalhos.  &nbsp; </p>\r\n\r\n\r\n\r\n<p><b>3º Dia &nbsp;</b><b>ORÇAMENTO E\r\nFINANÇAS NA POLÍTICA DE ASSISTÊNCIA SOCIAL </b><b></b></p>\r\n\r\n<p>8h - Dinâmica.</p>\r\n\r\n<p>8h30h – Estrutura do PPA, orçamento e\r\nfinanças na assistência Social</p>\r\n\r\n<p>9h30 – Trabalho em grupo</p>\r\